import assert from 'node:assert/strict';
import { parsePort } from './src/ports.js';
assert.equal(parsePort('1'), 1);
assert.equal(parsePort('65535'), 65535);
for (const value of ['0', '-1', '65536', '1.5', 'abc', '']) assert.throws(() => parsePort(value));
